<?php
session_start();include('check-login.php');include('dbstring.php');include_once('transport-utils.php');if(!transport_is_admin()){http_response_code(403);exit('Administrator access required.');}transport_ensure_tables($con);$msg='';$actor=isset($_SESSION['USERID'])?$_SESSION['USERID']:'';function tm($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
if(isset($_POST['save_vehicle'])){$n=trim((string)$_POST['vehiclename']);$reg=trim((string)$_POST['registrationno']);$cap=(int)$_POST['capacity'];if($n===''||$reg===''||$cap<1)$msg='Enter vehicle name, registration number, and capacity.';else{$id=transport_id('VEH_');$ok=mysqli_query($con,"INSERT INTO tbltransportvehicle(vehicleid,vehiclename,registrationno,capacity,driverid,assistantid,status,createdby,createdat) VALUES('$id','".mysqli_real_escape_string($con,$n)."','".mysqli_real_escape_string($con,$reg)."',$cap,'".mysqli_real_escape_string($con,$_POST['driverid'])."','".mysqli_real_escape_string($con,$_POST['assistantid'])."','active','".mysqli_real_escape_string($con,$actor)."',NOW())");$msg=$ok?'Vehicle saved.':'Vehicle could not be saved; registration number may already exist.';}}
if(isset($_POST['save_route'])){$n=trim((string)$_POST['routename']);if($n==='')$msg='Enter a route name.';else{$id=transport_id('RTE_');$ok=mysqli_query($con,"INSERT INTO tbltransportroute(routeid,routename,vehicleid,fee,status,createdby,createdat) VALUES('$id','".mysqli_real_escape_string($con,$n)."','".mysqli_real_escape_string($con,$_POST['vehicleid'])."',".(float)$_POST['fee'].",'active','".mysqli_real_escape_string($con,$actor)."',NOW())");$msg=$ok?'Route saved.':'Route could not be saved; route name may already exist.';}}
if(isset($_POST['save_stop'])){$id=transport_id('STP_');$ok=mysqli_query($con,"INSERT INTO tbltransportstop(stopid,routeid,stopname,pickuptime,sortorder,status,createdat) VALUES('$id','".mysqli_real_escape_string($con,$_POST['routeid'])."','".mysqli_real_escape_string($con,trim((string)$_POST['stopname']))."','".mysqli_real_escape_string($con,$_POST['pickuptime'])."',".(int)$_POST['sortorder'].",'active',NOW())");$msg=$ok?'Route stop saved.':'Stop could not be saved.';}
$staff=array();$r=mysqli_query($con,"SELECT userid,CONCAT_WS(' ',firstname,othernames,surname) name FROM tblsystemuser WHERE systemtype IN ('Teacher','User') AND status='active' ORDER BY firstname,surname");if($r)while($x=mysqli_fetch_assoc($r))$staff[]=$x;$vehicles=array();$r=mysqli_query($con,"SELECT * FROM tbltransportvehicle WHERE status='active' ORDER BY vehiclename");if($r)while($x=mysqli_fetch_assoc($r))$vehicles[]=$x;$routes=array();$r=mysqli_query($con,"SELECT tr.*,v.vehiclename FROM tbltransportroute tr LEFT JOIN tbltransportvehicle v ON v.vehicleid=tr.vehicleid WHERE tr.status='active' ORDER BY tr.routename");if($r)while($x=mysqli_fetch_assoc($r))$routes[]=$x;
?>
<!doctype html><html><head><?php include('links.php');?><title>Transport Management</title><style>body{background:#f4f8fb;font-family:Arial;color:#17314b}.tm{max-width:1100px;margin:25px auto;background:#fff;padding:24px;border-radius:16px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{border:1px solid #dce6ee;border-radius:12px;padding:16px}.card input,.card select{width:100%;box-sizing:border-box;padding:10px;margin:5px 0;background:#fff;color:#102a43;border:1px solid #7893aa;border-radius:7px}.card button{background:#087443;color:#fff;border:0;border-radius:8px;padding:11px 14px;margin-top:8px}.tm table{width:100%;border-collapse:collapse;margin-top:22px}.tm td,.tm th{padding:9px;border-bottom:1px solid #dce6ee;text-align:left}@media(max-width:700px){.tm{margin:8px;padding:14px}.grid{grid-template-columns:1fr}}</style></head><body><main class="tm"><h1>Transport Management</h1><p>Create vehicles, routes, and pickup stops. Then use Student Transport Assignment to place students on a route.</p><p><a href="transport-student-assignment.php">Assign Students to Transport →</a></p><?php if($msg!=='')echo '<p>'.tm($msg).'</p>';?><div class="grid"><section class="card"><h2>Vehicle</h2><form method="post"><input name="vehiclename" placeholder="Vehicle name" required><input name="registrationno" placeholder="Registration number" required><input type="number" name="capacity" min="1" placeholder="Capacity" required><select name="driverid"><option value="">Choose driver (optional)</option><?php foreach($staff as $s){?><option value="<?php echo tm($s['userid']);?>"><?php echo tm($s['name']);?></option><?php }?></select><select name="assistantid"><option value="">Choose assistant (optional)</option><?php foreach($staff as $s){?><option value="<?php echo tm($s['userid']);?>"><?php echo tm($s['name']);?></option><?php }?></select><button name="save_vehicle">Save Vehicle</button></form></section><section class="card"><h2>Route</h2><form method="post"><input name="routename" placeholder="Route name" required><select name="vehicleid"><option value="">Choose vehicle</option><?php foreach($vehicles as $v){?><option value="<?php echo tm($v['vehicleid']);?>"><?php echo tm($v['vehiclename'].' — '.$v['registrationno']);?></option><?php }?></select><input type="number" name="fee" min="0" step="0.01" placeholder="Transport fee per term (GHS)"><button name="save_route">Save Route</button></form></section><section class="card"><h2>Pickup Stop</h2><form method="post"><select name="routeid" required><option value="">Choose route</option><?php foreach($routes as $r){?><option value="<?php echo tm($r['routeid']);?>"><?php echo tm($r['routename']);?></option><?php }?></select><input name="stopname" placeholder="Stop name" required><input name="pickuptime" placeholder="Pickup time, e.g. 6:30 AM"><input type="number" name="sortorder" value="0" min="0" placeholder="Stop order"><button name="save_stop">Save Stop</button></form></section></div><h2>Active Routes</h2><table><tr><th>Route</th><th>Vehicle</th><th>Fee / Term</th></tr><?php foreach($routes as $r){?><tr><td><?php echo tm($r['routename']);?></td><td><?php echo tm($r['vehiclename']);?></td><td>GHS <?php echo number_format($r['fee'],2);?></td></tr><?php }?></table></main></body></html>
